"use strict";
// Session Logs for the Eclipse plugin: logs-entry.js and the vscode/ modules it requires, as one script for the
// plugin's browser, built by the same bundler as the analysis worker (frontend-bundle.js). Node's fs and path are not
// there: what needs them throws when used, and the parts used here do not.
const path = require("node:path");
const fs = require("node:fs");
const { build } = require("./frontend-bundle");

const EXTERNALS = {
  // The snapshot page's nonce, from the browser's own random source.
  crypto: "{ randomBytes: function (n) { var bytes = new Uint8Array(n); window.crypto.getRandomValues(bytes);"
    + " return { toString: function () { return Array.prototype.map.call(bytes, function (b) { return (b < 16 ? '0' : '') + b.toString(16); }).join(''); } }; } }",
  // Choosing the log folder starts from VS Code's settings and assistants (model-config.js): not part of reading a log.
  "./chat": "new Proxy({}, {get: () => () => {throw new Error('Chat actions belong to the host');}})",
  "./review-jev": "new Proxy({}, {get: () => () => {throw new Error('Decision provider selection belongs to the host');}})",
  "./topic-backfill": "new Proxy({}, {get: () => () => {throw new Error('Topic tagging belongs to the host');}})",
  "./model-config": "new Proxy({}, { get: function () { return function () { throw new Error('Choosing the log folder is VS Code\\'s; Eclipse has its own.'); }; } })"
};

function bundle(root = path.join(__dirname, "..")) {
  // The browser reads question observations only; routing imports server-side model transports.
  const routing = fs.readFileSync(path.join(root, "vscode/topic-routing.js"), "utf8");
  const observations = routing.slice(routing.indexOf("function observations("), routing.indexOf("function catalog("));
  const clip = routing.slice(routing.indexOf("const clip="), routing.indexOf("function scopeOf("));
  const select = fs.readFileSync(path.join(root, "vscode/select-query.js"), "utf8");
  const loggedSource = select.slice(select.indexOf("function loggedSource("), select.indexOf("function prepare("));
  const externals = { ...EXTERNALS, "../vscode/select-query": "(() => {" + loggedSource + ";return {loggedSource};})()", "./topic-routing": "(() => {" + clip + observations + ";return {observations};})()" };
  return "// Generated by eclipse/prepare.js from eclipse/logs-entry.js and the vscode/ modules it requires - edit those.\n"
    + build(root, [["vertexLogs", "eclipse/logs-entry.js"]], { externals }) + "\n";
}

module.exports = { bundle };
